// collage.js — generated by the collage editor. Renders a collage document to HTML.

export const BREAKPOINTS = ['sm', 'md', 'lg'];

// Container widths (not viewport widths) where each layout takes over. Keep in sync with the
// @container rules in collage.css.
export const BREAKPOINT_MIN = { sm: 0, md: 640, lg: 1024 };

export const DEFAULT_GRID = {
  sm: { cols: 24, rows: 24 },
  md: { cols: 36, rows: 24 },
  lg: { cols: 48, rows: 24 },
};

export const FRAME_DEFAULTS = {
  none: {},
  window: { title: 'Untitled', toolbar: false, address: 'http://www.example.com/' },
  safari: { title: 'Welcome', address: 'http://www.example.com/', bookmarks: true },
  polaroid: { style: 'classic', caption: '', showCaption: false },
  stamp: { style: 'classic', value: '25¢', label: 'POSTAGE', postmarked: false, city: 'CHICAGO, IL', date: 'OCT 22 1998' },
  selection: { color: 'blue', name: 'Frame 1', showName: true, size: '1200 × 800', showSize: true },
  textedit: { title: 'Untitled', edited: true, appearance: 'light', formatBar: true, ruler: true, text: '', showImage: true },
};

// Sticky notes are items with kind: 'note' and no image.
export const NOTE_DEFAULTS = { style: 'postit', color: 'yellow', text: '' };

const ENTITIES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ENTITIES[c]);
const clamp = (n, min, max) => Math.min(Math.max(n, min), max);

export function gridFor(doc) {
  return { ...DEFAULT_GRID, ...(doc.grid || {}) };
}

// A placement set by hand wins. Otherwise derive one from the largest layout that has one:
// positions scale with each axis; size scales uniformly so the item keeps its shape and the
// same share of the canvas's area.
export function resolvePlacement(item, bp, grid) {
  const own = item.place?.[bp];
  if (own) return { ...own, auto: false };
  const from = ['lg', 'md', 'sm'].find((key) => item.place?.[key]);
  if (!from) return { x: 1, y: 1, w: 4, h: 4, auto: true };
  const src = item.place[from];
  const a = grid[from];
  const b = grid[bp];
  const scale = Math.sqrt((b.cols * b.rows) / (a.cols * a.rows));
  const w = clamp(Math.round(src.w * scale), 1, b.cols);
  const h = clamp(Math.round(src.h * scale), 1, b.rows);
  const x = clamp(Math.round(((src.x - 1) * b.cols) / a.cols) + 1, 1, b.cols - w + 1);
  const y = clamp(Math.round(((src.y - 1) * b.rows) / a.rows) + 1, 1, b.rows - h + 1);
  return { x, y, w, h, hidden: !!src.hidden, auto: true };
}

// Frame chrome around the image in design pixels (a cell is 24): [left + right, top + bottom].
const CHROME = {
  window: (f) => [10, 26 + (f.toolbar ? 26 : 0)],
  safari: (f) => [6, 22 + 31 + 15 + (f.bookmarks ? 20 : 0)],
  polaroid: () => [32, 96],
  stamp: (f) => (f.style === 'vintage' ? [36, 82] : f.style === 'modern' ? [18, 18] : f.style === 'airmail' ? [40, 56] : [20, 50]),
  textedit: (f) => [30, 28 + (f.formatBar ? 28 : 0) + (f.ruler ? 22 : 0) + 22],
};

/** @returns {[number, number]} */
export function frameChrome(item) {
  const type = item.frame?.type || 'none';
  return CHROME[type]?.({ ...FRAME_DEFAULTS[type], ...item.frame }) ?? [0, 0];
}

/**
 * How wide an item's image is drawn at each layout size where it shows, as a fraction of the
 * collage's width. Everything in a collage scales with its width, so this holds at any width.
 * A covering image that gets cropped is drawn wider than its frame.
 * @param {{ width: number, height: number }} size The image's pixel size.
 * @returns {{ sm?: number, md?: number, lg?: number }}
 */
export function imageScale(item, grid, size) {
  const [chromeX, chromeY] = frameChrome(item);
  /** @type {{ sm?: number, md?: number, lg?: number }} */
  const scales = {};
  for (const bp of BREAKPOINTS) {
    const p = resolvePlacement(item, bp, grid);
    if (p.hidden) continue;
    const cell = 1 / grid[bp].cols; // cells are square, so heights use the same unit
    const px = (cell / 24) * effectsAt(item, bp).frameScale;
    const w = Math.max(p.w * cell - chromeX * px, 0);
    const h = Math.max(p.h * cell - chromeY * px, 0);
    const fitted = (h * size.width) / size.height;
    scales[bp] = item.fit === 'contain' ? Math.min(w, fitted) : Math.max(w, fitted);
  }
  return scales;
}

// Frame scale and rotation at a layout size. Large's are the item's own; Medium and Small can
// override them in item.at, and a size without its own follows Large.
export function effectsAt(item, bp) {
  const own = bp === 'lg' ? {} : item.at?.[bp] || {};
  return { frameScale: own.frameScale ?? item.frameScale ?? 1, r: own.r ?? item.r ?? 0 };
}

// The image's share of the viewport at each layout, for srcset selection.
export function sizesFor(item, grid) {
  return [...BREAKPOINTS]
    .reverse()
    .map((bp) => {
      const vw = Math.ceil((resolvePlacement(item, bp, grid).w / grid[bp].cols) * 100);
      return bp === 'sm' ? `${vw}vw` : `(min-width: ${BREAKPOINT_MIN[bp]}px) ${vw}vw`;
    })
    .join(', ');
}

function renderImage(item, grid, image) {
  const img = (image && image(item)) || {};
  const sizes = img.sizes || sizesFor(item, grid);
  const attrs = ['class="CollageImage"', `src="${esc(img.src)}"`, `alt="${esc(item.alt)}"`];
  if (img.srcset) attrs.push(`srcset="${esc(img.srcset)}"`, `sizes="${esc(sizes)}"`);
  if (img.width && img.height) attrs.push(`width="${img.width}"`, `height="${img.height}"`);
  attrs.push(`loading="${img.loading === 'eager' ? 'eager' : 'lazy'}"`, 'decoding="async"');
  if (img.fetchpriority) attrs.push(`fetchpriority="${esc(img.fetchpriority)}"`);
  const style = [];
  if (item.fit && item.fit !== 'cover') style.push(`--fit:${item.fit}`);
  if (item.focus && (item.focus[0] !== 50 || item.focus[1] !== 50)) style.push(`--focus:${item.focus[0]}% ${item.focus[1]}%`);
  if (style.length) attrs.push(`style="${style.join(';')}"`);
  const tag = `<img ${attrs.join(' ')}>`;
  if (!img.sources?.length) return tag;
  // Other formats (AVIF, say), which the browser takes over the <img>'s when it can.
  const sources = img.sources.map((s) => `<source type="${esc(s.type)}" srcset="${esc(s.srcset)}" sizes="${esc(sizes)}">`).join('');
  return `<picture class="CollagePicture">${sources}${tag}</picture>`;
}

function macWindow(f, img) {
  const toolbar = f.toolbar
    ? `<div class="MacWindow__toolbar" aria-hidden="true"><span class="MacWindow__button MacWindow__button--back"></span><span class="MacWindow__button MacWindow__button--forward"></span><span>Location:</span><span class="MacWindow__address">${esc(f.address)}</span></div>`
    : '';
  // An untitled window's stripes run unbroken from box to box.
  const title = f.title?.trim()
    ? `<span class="MacWindow__stripes"></span><span class="MacWindow__title">${esc(f.title)}</span><span class="MacWindow__stripes"></span>`
    : '<span class="MacWindow__stripes"></span>';
  return `<div class="MacWindow"><div class="MacWindow__titleBar" aria-hidden="true"><span class="MacWindow__box"></span>${title}<span class="MacWindow__box MacWindow__box--collapse"></span></div>${toolbar}<div class="MacWindow__content">${img}</div></div>`;
}

function safariWindow(f, img) {
  const bookmarks = f.bookmarks
    ? '<div class="SafariWindow__bookmarks" aria-hidden="true"><span>Apple</span><span>Amazon</span><span>eBay</span><span>Yahoo!</span><span>News</span></div>'
    : '';
  return `<div class="SafariWindow"><div class="SafariWindow__titleBar" aria-hidden="true"><span class="SafariWindow__lights"><span class="SafariWindow__light"></span><span class="SafariWindow__light"></span><span class="SafariWindow__light"></span></span><span class="SafariWindow__title">${esc(f.title)}</span><span class="SafariWindow__pill"></span></div><div class="SafariWindow__toolbar" aria-hidden="true"><span class="SafariWindow__button SafariWindow__button--back"></span><span class="SafariWindow__button SafariWindow__button--forward"></span><span class="SafariWindow__button SafariWindow__button--reload"></span><span class="SafariWindow__button SafariWindow__button--add"></span><span class="SafariWindow__address"><span class="SafariWindow__url">${esc(f.address)}</span></span><span class="SafariWindow__search">Google</span></div>${bookmarks}<div class="SafariWindow__content">${img}</div><div class="SafariWindow__bottom" aria-hidden="true"></div></div>`;
}

function polaroid(f, img) {
  const tape = f.style === 'vintage' ? '<span class="Polaroid__tape" aria-hidden="true"></span>' : '';
  return `<div class="Polaroid Polaroid--${esc(f.style)}">${tape}<div class="Polaroid__photo">${img}</div><div class="Polaroid__caption">${f.showCaption ? esc(f.caption) : ''}</div></div>`;
}

function postmark(f) {
  const waves = [14, 24, 34, 44, 54].map((y) => `<path d="M0 ${y}q7-5 14 0t14 0 14 0 14 0"/>`).join('');
  return `<svg class="Stamp__postmark" viewBox="0 0 124 72" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="2">${waves}<circle cx="90" cy="34" r="30"/><circle cx="90" cy="34" r="25" stroke-width="1"/></g><g fill="currentColor" font-family="Oswald, 'Arial Narrow', sans-serif" font-size="7.5" font-weight="500" letter-spacing=".4" text-anchor="middle"><text x="90" y="32">${esc(f.city)}</text><text x="90" y="43">${esc(f.date)}</text></g></svg>`;
}

function stamp(f, img) {
  return `<div class="Stamp Stamp--${esc(f.style)}"><div class="Stamp__inner"><div class="Stamp__photo">${img}</div><span class="Stamp__value">${esc(f.value)}</span><span class="Stamp__label">${esc(f.label)}</span></div>${f.postmarked ? postmark(f) : ''}</div>`;
}

// A note's text, with each line the host's link(text, item) recognizes made a link. link() returns
// an href, or the <a>'s attributes; without it (as in the editor) the text stays plain. nav says
// whether the note is a list of links: two or more, and nothing else.
function noteText(text, item, link) {
  const lines = String(text ?? '').split('\n');
  let links = 0;
  const html = lines
    .map((line) => {
      const label = line.trim();
      const target = label && link?.(label, item);
      if (!target) return esc(line);
      links++;
      const attrs = Object.entries(typeof target === 'string' ? { href: target } : target)
        .filter(([name, value]) => /^[a-z][a-z-]*$/.test(name) && value != null)
        .map(([name, value]) => ` ${name}="${esc(value)}"`)
        .join('');
      const start = line.indexOf(label);
      return `${esc(line.slice(0, start))}<a${attrs}>${esc(label)}</a>${esc(line.slice(start + label.length))}`;
    })
    .join('\n');
  return { html, nav: links > 1 && links === lines.filter((line) => line.trim()).length };
}

function stickyNote(item, link) {
  const n = { ...NOTE_DEFAULTS, ...item.note };
  const text = noteText(n.text, item, link);
  // A TextEdit note is the TextEdit window holding text alone; its window options live on the note.
  if (n.style === 'textedit') return textEdit({ ...FRAME_DEFAULTS.textedit, ...n, showImage: false }, '', text.html);
  const chrome =
    n.style === 'stickies'
      ? '<div class="StickyNote__titleBar" aria-hidden="true"><span class="StickyNote__box"></span><span class="StickyNote__box StickyNote__box--zoom"></span></div>'
      : '';
  // A note of nothing but links is a menu: the site's nav, say.
  const tag = text.nav ? 'nav' : 'div';
  return `<div class="StickyNote StickyNote--${esc(n.style)} StickyNote--${esc(n.color)}">${chrome}<${tag} class="StickyNote__text">${text.html}</${tag}></div>`;
}

function textEdit(f, img, text = esc(f.text)) {
  const control = (cls, inner = '') => `<span class="TextEdit__control ${cls}">${inner}</span>`;
  const lines = (align) => `<span><span class="TextEdit__lines TextEdit__lines--${align}"></span></span>`;
  const formatBar = f.formatBar
    ? `<div class="TextEdit__formatBar" aria-hidden="true">${[
        control('TextEdit__popup', '¶'),
        control('TextEdit__popup TextEdit__popup--wide', 'Helvetica'),
        control('TextEdit__popup', 'Regular'),
        control('TextEdit__popup', '12'),
        control('TextEdit__well'),
        control('TextEdit__well TextEdit__well--highlight'),
        control('TextEdit__segments', '<b>B</b><i>I</i><u>U</u>'),
        control('TextEdit__segments', ['left', 'center', 'right', 'justify'].map(lines).join('')),
        control('TextEdit__popup', '1.0'),
        control('TextEdit__popup', '<span class="TextEdit__lines"></span>'),
      ].join('')}</div>`
    : '';
  const ruler = f.ruler ? `<div class="TextEdit__ruler" aria-hidden="true">${Array.from({ length: 12 }, (_, i) => `<span>${i + 1}</span>`).join('')}</div>` : '';
  const edited = f.edited ? '<span class="TextEdit__edited"> — Edited</span>' : '';
  return `<div class="TextEdit TextEdit--${esc(f.appearance)}"><div class="TextEdit__titleBar" aria-hidden="true"><span class="TextEdit__lights"><span class="TextEdit__light"></span><span class="TextEdit__light"></span><span class="TextEdit__light"></span></span><span class="TextEdit__title">${esc(f.title)}${edited}</span></div>${formatBar}${ruler}<div class="TextEdit__page"><p class="TextEdit__text">${text}</p>${f.showImage ? `<div class="TextEdit__content">${img}</div>` : ''}</div></div>`;
}

const COMPONENT_ICON = '<svg viewBox="0 0 12 12" aria-hidden="true"><path fill="currentColor" d="M6 .8 8.2 3 6 5.2 3.8 3zM3 3.8 5.2 6 3 8.2.8 6zm6 0L11.2 6 9 8.2 6.8 6zM6 6.8 8.2 9 6 11.2 3.8 9z"/></svg>';

function selection(f, img) {
  const handles = ['nw', 'ne', 'sw', 'se'].map((corner) => `<span class="Selection__handle Selection__handle--${corner}"></span>`).join('');
  const name = f.showName ? `<span class="Selection__name">${f.color === 'component' ? COMPONENT_ICON : ''}<span>${esc(f.name)}</span></span>` : '';
  const size = f.showSize ? `<span class="Selection__size">${esc(f.size)}</span>` : '';
  return `<div class="Selection Selection--${esc(f.color)}"><div class="Selection__content">${img}</div><div class="Selection__box" aria-hidden="true">${handles}${name}${size}</div></div>`;
}

export function renderFrame(item, img) {
  const type = item.frame?.type || 'none';
  const f = { ...FRAME_DEFAULTS[type], ...item.frame };
  if (type === 'window') return macWindow(f, img);
  if (type === 'safari') return safariWindow(f, img);
  if (type === 'textedit') return textEdit(f, img);
  if (type === 'polaroid') return polaroid(f, img);
  if (type === 'stamp') return stamp(f, img);
  if (type === 'selection') return selection(f, img);
  return `<div class="CollageItem__media">${img}</div>`;
}

export function renderItem(item, grid, image, link) {
  const vars = [];
  for (const bp of BREAKPOINTS) {
    const p = resolvePlacement(item, bp, grid);
    vars.push(`--${bp}-x:${p.x}`, `--${bp}-y:${p.y}`, `--${bp}-w:${p.w}`, `--${bp}-h:${p.h}`);
    if (p.hidden) vars.push(`--${bp}-show:none`);
  }
  vars.push(`--z:${item.z ?? 1}`);
  if (item.r) vars.push(`--r:${item.r}`);
  if (item.frameScale && item.frameScale !== 1) vars.push(`--frame-scale:${item.frameScale}`);
  for (const bp of ['md', 'sm']) {
    const own = item.at?.[bp];
    if (own?.frameScale != null) vars.push(`--${bp}-scale:${own.frameScale}`);
    if (own?.r != null) vars.push(`--${bp}-r:${own.r}`);
  }
  const cls = ['CollageItem', item.shadow && 'CollageItem--shadow', item.sticker && 'CollageItem--sticker'].filter(Boolean).join(' ');
  const body = item.kind === 'note' ? stickyNote(item, link) : renderFrame(item, renderImage(item, grid, image));
  return `<div class="${cls}" data-id="${esc(item.id)}" style="${vars.join(';')}">${body}</div>`;
}

// The sticker border's last step (see .CollageItem--sticker in collage.css). CSS filters can't
// sharpen alpha, so an SVG filter steepens the border's edge.
const STICKER_EDGE =
  '<svg class="Collage__defs" width="0" height="0" aria-hidden="true" focusable="false">' +
  '<filter id="collage-sticker-edge" x="-50%" y="-50%" width="200%" height="200%" color-interpolation-filters="sRGB">' +
  '<feComponentTransfer><feFuncA type="linear" slope="3" intercept="-1"/></feComponentTransfer>' +
  '</filter></svg>';

/**
 * @typedef {object} CollageImageSource
 * @property {string} [src]
 * @property {string} [srcset]
 * @property {string} [sizes]
 * @property {number} [width]
 * @property {number} [height]
 * @property {{ type: string, srcset: string }[]} [sources] Other formats, offered in a <picture>.
 * @property {'lazy' | 'eager'} [loading]
 * @property {'high' | 'low' | 'auto'} [fetchpriority]
 */

/**
 * Renders a collage document to HTML. image(item) returns the source for an item's image;
 * link(text, item) turns a line of a note into a link (see noteText).
 * @param {{ items: object[], grid?: object }} doc
 * @param {{ image?: (item: any) => CollageImageSource | undefined, link?: (text: string, item: any) => string | Record<string, string> | undefined, className?: string }} [options]
 * @returns {string}
 */
export function renderCollage(doc, { image, link, className = '' } = {}) {
  const grid = gridFor(doc);
  const vars = BREAKPOINTS.map((bp) => `--${bp}-cols:${grid[bp].cols};--${bp}-rows:${grid[bp].rows}`).join(';');
  const items = [...doc.items]
    .sort((a, b) => (a.z ?? 0) - (b.z ?? 0))
    .map((item) => renderItem(item, grid, image, link))
    .join('');
  const defs = doc.items.some((item) => item.sticker) ? STICKER_EDGE : '';
  return `<div class="Collage${className ? ` ${esc(className)}` : ''}" style="${vars}">${defs}<div class="Collage__grid">${items}</div></div>`;
}
